-- Report ID : RPT_001
-- Report    : DC Adjustments
-- Module    : Inventory
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     ia.LOCATION                                         AS location_id,     ia.LOC_TYPE                                         AS location_type,     CASE ia.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                 AS location_name,     ia.REASON                                           AS reason_code,     rt.REASON_DESC                                      AS reason_description,     COUNT(ia.ID)                                        AS total_adjustments,     SUM(ia.ADJ_QTY)                                     AS total_adj_units,     SUM(CASE WHEN ia.ADJ_QTY > 0 THEN  ia.ADJ_QTY ELSE 0 END) AS positive_adj_units,     SUM(CASE WHEN ia.ADJ_QTY < 0 THEN  ia.ADJ_QTY ELSE 0 END) AS negative_adj_units,     ROUND(SUM(ia.ADJ_QTY * ils.UNIT_COST),  2)         AS total_adj_cost,     ROUND(SUM(CASE WHEN ia.ADJ_QTY > 0                    THEN ia.ADJ_QTY * ils.UNIT_COST                    ELSE 0 END), 2)                      AS positive_adj_cost,     ROUND(SUM(CASE WHEN ia.ADJ_QTY < 0                    THEN ia.ADJ_QTY * ils.UNIT_COST                    ELSE 0 END), 2)                      AS negative_adj_cost,     ROUND(SUM(ia.ADJ_QTY * il.SELLING_UNIT_RETAIL), 2) AS total_adj_retail,     ROUND(SUM(CASE WHEN ia.ADJ_QTY > 0                    THEN ia.ADJ_QTY * il.SELLING_UNIT_RETAIL                    ELSE 0 END), 2)                      AS positive_adj_retail,     ROUND(SUM(CASE WHEN ia.ADJ_QTY < 0                    THEN ia.ADJ_QTY * il.SELLING_UNIT_RETAIL                    ELSE 0 END), 2)                      AS negative_adj_retail,     ROUND(SUM(ia.ADJ_QTY * (il.SELLING_UNIT_RETAIL - ils.UNIT_COST)), 2)                                                         AS gross_profit_impact  FROM     MFCS_RDS.RDS_WV_INV_ADJ                    ia      LEFT JOIN MFCS_RDS.RDS_WV_INV_ADJ_REASON_TL rt                                                 ON  ia.REASON       = rt.REASON                                                 AND rt.LANG          = 1      LEFT JOIN MFCS_RDS.RDS_WV_STORE             st  ON  ia.LOCATION = st.STORE                                                     AND  ia.LOC_TYPE = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH                wh  ON  ia.LOCATION = wh.WH                                                     AND  ia.LOC_TYPE = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH     ils  ON  ia.ITEM     = ils.ITEM                                                     AND  ia.LOCATION = ils.LOC                                                     AND  ia.LOC_TYPE = ils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC           il  ON  ia.ITEM     = il.ITEM                                                     AND  ia.LOCATION = il.LOC                                                     AND  ia.LOC_TYPE = il.LOC_TYPE  WHERE     ia.ADJ_DATE >= ADD_MONTHS(SYSDATE, -3)    GROUP BY     ia.LOCATION,     ia.LOC_TYPE,     CASE ia.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END,     ia.REASON,     rt.REASON_DESC  ORDER BY     ia.LOCATION,     ia.REASON